import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import Redis from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL);
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Session-based access control
app.use(express.json());

// Middleware: rate limiting via Redis
app.use(async (req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const key = `rl:${ip}:${Math.floor(Date.now() / 60000)}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  next();
});

// User document search endpoint
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, tenant_id, page = '1', fields } = req.query;
  const sessionToken = req.headers['x-session-token'];

  if (!sessionToken || !tenant_id) {
    return res.status(401).json({ error: 'unauthorized' });
  }

  // Validate session
  const session = await redis.hgetall(`sess:${sessionToken}`);
  if (!session || !session.user_id) {
    return res.status(401).json({ error: 'invalid session' });
  }

  // Tenant isolation check
  if (session.tenant_id !== tenant_id) {
    return res.status(403).json({ error: 'tenant mismatch' });
  }

  const offset = (parseInt(page) - 1) * 25;

  // Build field selection - developer assumed fields are column names
  let selectClause = 'id, title, created_at, owner_id';
  if (fields) {
    // "Sanitization" - remove obvious SQL keywords
    const cleaned = fields.replace(/;|--|\/\*|\*\//g, '');
    selectClause = cleaned;
  }

  try {
    const query = `
      SELECT ${selectClause}
      FROM documents 
      WHERE tenant_id = $1 
        AND (title ILIKE $2 OR content ILIKE $2)
        AND deleted_at IS NULL
      ORDER BY created_at DESC
      LIMIT 25 OFFSET $3
    `;
    const result = await pool.query(query, [tenant_id, `%${q}%`, offset]);

    // Audit log
    await redis.xadd('audit:searches', '*',
      'user_id', session.user_id,
      'tenant_id', tenant_id,
      'query', q || '',
      'fields', fields || 'default',
      'results', String(result.rows.length)
    );

    res.json({
      data: result.rows,
      pagination: { page: parseInt(page), per_page: 25 }
    });
  } catch (err) {
    const errorId = crypto.randomUUID();
    console.error(`[${errorId}]`, err.message);
    // Never expose internal errors
    res.status(500).json({ error: 'internal error', ref: errorId });
  }
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
